// Chat AI frontend push 19.11.26 16:12 CET: 9 keys 983841258-266 -> AICHAT-1729 (Task, epic AICHAT-1713), PR #1038. Tags merged; descriptions only where empty.
const BTN = [
  'Where: "Share image" window (a pop-up on computers, a panel that slides up from the bottom on phones), opened from an AI-generated image. Under the image there is a row of round icon buttons with a short label under each.',
  'What: Button labels. images::share::download "Download" = save the image file to the device (verb, an action). images::share::more "More" = opens the phone\'s own sharing menu (messengers, mail, other apps); shown on phones only. images::share::copied "Copied" = what the "Copy link" button shows for 2 seconds after the link was copied, next to a tick icon.',
  'Meaning: "Download" is the action, not the noun "a download". "More" = more ways to share, not "more images". "Copied" = the link has been copied (a state, not a command).',
  'Refers to: "Copied" refers to the link - images::share::copyLink "Copy link" on the same button. If your language needs agreement, agree with "link".',
  'Goes with: images::share::copyLink "Copy link", images::share::download "Download" and images::share::more "More" sit side by side - use the same form for all (same verb form, same capitalisation), short.',
  'Length: each label sits under its icon in a column about 60 px wide on phones and 80 px on computers - about 10 characters, ideally one word.'
].join('\n');
